  rfSidePlankDip: { "pos": "En gainage latéral, appui sur l\u2019avant-bras et le pied, corps aligné.", "move": "Descends le bassin vers le sol sans le poser, puis remonte à la position de gainage initiale, mouvement contrôlé.", "avoid": "Ne pas laisser le bassin tourner vers l\u2019avant ou l\u2019arrière \u2014 le mouvement reste purement vertical." },
  rfPushKnee: { "pos": "Position de pompe sur les genoux, corps aligné des genoux à la tête, mains un peu plus larges que les épaules.", "move": "Descends la poitrine vers le sol en gardant les coudes à 45°, puis pousse pour remonter.", "avoid": "Ne pas laisser le bassin remonter ou descendre \u2014 garde la ligne droite des genoux à la tête." },
  rfPushIncline: { "pos": "Mains posées sur un banc, une table ou un mur stable, corps incliné, pieds au sol.", "move": "Descends la poitrine vers l\u2019appui en fléchissant les coudes à 45° du corps, puis repousse pour remonter.", "avoid": "Ne pas utiliser un appui instable \u2014 vérifie qu\u2019il ne glissera pas pendant le mouvement." },
