  rfPushWide: { "pos": "Position de pompe, mains plus écartées que la largeur des épaules.", "move": "Descends la poitrine vers le sol en gardant les coudes ouverts à environ 60°, puis repousse pour remonter.", "avoid": "Ne pas descendre trop bas si l\u2019épaule tire \u2014 cette version sollicite davantage les pectoraux mais aussi plus l\u2019articulation." },
  rfPushDiamond: { "pos": "Position de pompe, mains rapprochées formant un triangle, pouces et index qui se touchent.", "move": "Descends la poitrine vers les mains en gardant les coudes proches du corps, puis repousse fort.", "avoid": "Ne pas écarter les coudes \u2014 c\u2019est leur position serrée qui rend cet exercice très ciblé triceps." },
  rfDipsBench: { "pos": "Mains pos\u00e9es sur un banc derri\u00e8re toi, pieds pos\u00e9s sur un second banc devant, bras tendus.", "move": "Descends en pliant les coudes vers l\u2019arri\u00e8re jusqu\u2019\u00e0 un angle confortable, puis repousse pour remonter bras tendus.", "avoid": "Ne pas descendre trop bas si \u00e7a tire dans l\u2019\u00e9paule \u2014 limite l\u2019amplitude \u00e0 ce qui reste sans douleur." },
  rfLatRaise: { "pos": "Debout, bras le long du corps, charge légère en main.", "move": "Monte les bras tendus sur les côtés jusqu\u2019à hauteur d\u2019épaule, en gardant un léger fléchissement aux coudes, puis redescends lentement.", "avoid": "Ne pas monter au-dessus de l\u2019épaule ni utiliser l\u2019élan \u2014 le mouvement doit rester lent et contrôlé." },
